sap.ui.define([
  "sap/ui/model/Filter",
  "sap/ui/model/FilterOperator"
], function (Filter, FilterOperator) {
  "use strict";

  // (Category = "Laptops" OR Category = "Tablets") AND Price < 1000
  const byCategory = new Filter({
    filters: [
      new Filter("Category", FilterOperator.EQ, "Laptops"),
      new Filter("Category", FilterOperator.EQ, "Tablets")
    ],
    and: false
  });
  const cheap = new Filter("Price", FilterOperator.LT, 1000);

  const finalFilter = new Filter({ filters: [byCategory, cheap], and: true });

  // in a controller:
