assignment.solution:
onSearch: function (event) {
  const query = event.getParameter("query");
  const filters = [];
  if (query) {
    filters.push(new Filter({
      path: "Name",
      operator: FilterOperator.Contains,
      value1: query,
      caseSensitive: false
    }));
  }
  this.byId("productList").getBinding("items").filter(filters);
}

