sap.ui.define([
  "sap/ui/core/format/DateFormat",
  "sap/ui/core/format/NumberFormat",
  "sap/ui/core/format/FileSizeFormat"
], function (DateFormat, NumberFormat, FileSizeFormat) {
  "use strict";

  const date = DateFormat.getDateInstance({ pattern: "dd.MM.yyyy" });
  date.format(new Date(2024, 0, 15));        // "15.01.2024"

  const price = NumberFormat.getCurrencyInstance();
  price.format(1234.5, "EUR");                // for example "EUR 1,234.50" (depends on the locale)

  const weight = NumberFormat.getUnitInstance();
  weight.format(12, "mass-kilogram");         // for example "12 kg"

  const size = FileSizeFormat.getInstance();
  size.format(1500000);                       // for example "1.5 MB"
});

