// View: <VBox items="{path: '/Fields', factory: '.createField'}" />

createField: function (id, context) {
  const type = context.getProperty("type");
  switch (type) {
    case "date":
      return new DatePicker(id, { value: "{value}" });
    case "boolean":
      return new CheckBox(id, { selected: "{value}", text: "{label}" });
    default:
      return new Input(id, { value: "{value}", placeholder: "{label}" });
  }
}

const evenStock = new Filter({
  path: "Stock",
  test: function (stock) {
    return stock % 2 === 0;
  }
});

this.byId("productList").getBinding("items").filter(evenStock);

const priceRange = function (context) {
  const price = context.getProperty("Price");
  if (price < 100) {
    return { key: "low", text: "Under 100" };
  }
  if (price < 1000) {
    return { key: "mid", text: "100 to 999" };
  }
  return { key: "high", text: "1000 and more" };
};

this.byId("productList").getBinding("items").sort(
  new Sorter("Price", false, priceRange)
);

sap.ui.define([
  "sap/ui/model/SimpleType",
  "sap/ui/model/ValidateException"
], function (SimpleType, ValidateException) {
  "use strict";

  return SimpleType.extend("my.app.model.type.Email", {
    formatValue: function (value) {
      return value;
    },
    parseValue: function (value) {
      return value ? value.trim().toLowerCase() : value;
    },
    validateValue: function (value) {
      if (value && !/^\S+@\S+\.\S+$/.test(value)) {
        throw new ValidateException("'" + value + "' is not a valid e-mail address");
      }
    }
  });
});

